// trigger: REQUIREMENT_LOGGED / CLARIFICATION_READY / JD_REJECTED → emit: JD_GENERATED
// 参考脚手架：运行时按 workflow manifest 的 action[] 声明式调度执行（systemPrompt + 工具），
// 【不直接运行这段 .ts 代码】——它是可读/可改的 agent 定义参考。真·CodeAct 执行路径用 codeExecuted 开关（默认关）。

/** Input/Output schema — 依据本体 DataObjects 定义。 */
interface CreateJDAgentInput {
  requirement_id: string; // 事件 REQUIREMENT_LOGGED 的 payload 字段
  client_id: string; // 目标客户唯一编号
  source_channel: unknown; // 事件 REQUIREMENT_LOGGED 的 payload 字段
  raw_input_data: Record<string, unknown>; // 事件 REQUIREMENT_LOGGED 的 payload 字段
  is_urgent: boolean; // 事件 REQUIREMENT_LOGGED 的 payload 字段
  clarification_status: string; // 事件 CLARIFICATION_READY 的 payload 字段
  must_have_skills: unknown; // 事件 CLARIFICATION_READY 的 payload 字段 (源: Job_Requisition.must_have_skills)
  nice_to_have_skills: unknown; // 事件 CLARIFICATION_READY 的 payload 字段 (源: Job_Requisition.nice_to_have_skills)
  negative_requirement: string; // 事件 CLARIFICATION_READY 的 payload 字段 (源: Job_Requisition.negative_requirement)
  clarify_questions: unknown; // 事件 CLARIFICATION_READY 的 payload 字段 (源: Job_Requisition.clarify_questions)
  degree_requirement: string; // 事件 CLARIFICATION_READY 的 payload 字段 (源: Job_Requisition.degree_requirement)
  work_years: number; // 事件 CLARIFICATION_READY 的 payload 字段 (源: Job_Requisition.work_years)
  city: string; // 事件 CLARIFICATION_READY 的 payload 字段 (源: Job_Requisition.city)
  required_arrival_date: unknown; // 事件 CLARIFICATION_READY 的 payload 字段 (源: Job_Requisition.required_arrival_date)
  interview_mode: string; // 事件 CLARIFICATION_READY 的 payload 字段 (源: Job_Requisition.interview_mode)
  headcount: number; // 事件 CLARIFICATION_READY 的 payload 字段 (源: Job_Requisition.headcount)
  job_responsibility: string; // 事件 CLARIFICATION_READY 的 payload 字段 (源: Job_Requisition.job_responsibility)
  jd_id: string; // 事件 JD_REJECTED 的 payload 字段
  rejector_id: string; // 事件 JD_REJECTED 的 payload 字段
  rejection_reason_code: unknown; // 事件 JD_REJECTED 的 payload 字段
  feedback_details: string; // 事件 JD_REJECTED 的 payload 字段
  revision_number: number; // 事件 JD_REJECTED 的 payload 字段
  job_requisition_id: string; // 已完成需求澄清的招聘岗位唯一编号 (源: Job_Requisition.job_requisition_id)
}

interface CreateJDAgentOutput {
  job_posting_id: string; // 生成的岗位发布信息唯一编号 (源: Job_Posting.job_posting_id)
  jd_content: string; // 生成的完整JD内容
}

/** System prompt — 工厂为【这一个】agent 亲自推理出来的。 */
const SYSTEM_PROMPT = `你是一个专业的职位描述（JD）生成专家。你的核心职责是基于已澄清的招聘需求，自动生成标准化、具吸引力且合规的对外职位发布信息。

工作流程：
1. 接收输入：获取 \`job_requisition_id\` 和 \`client_id\`。
2. 动态获取规则：必须调用 \`ontology.fetchActionRules\` 获取当前动作（\`createJD\`）的最新业务规则。
3. 规则应用与内容生成：
   - 严格执行获取到的规则，特别是“职位敏感信息脱敏规则”（移除客户名称）和“职位歧视性敏感信息脱敏规则”。
   - 执行“岗位发布精准性规则”，生成符合市场认知的标题和关键词。
   - 检查“职位不当福利承诺过滤规则”，确保福利描述真实合规。
   - 评估“招聘需求聚合发布”规则，若条件满足则合并 JD。
4. 内容归档：使用 \`fs.writeMarkdownToArchive\` 将最终生成的 JD 文本持久化保存。
5. 产出结果：输出生成的 \`job_posting_id\` 和完整的 \`jd_content\`。

决策依据：
- 必须依赖动态获取的规则进行脱敏和聚合判断，绝不可凭空捏造规则或硬编码。
- 保证输出的 JD 语句通顺、专业，且不包含任何违规或敏感信息。

【前置条件（运行前必须满足；不满足则 fail-close 发拦截/失败事件，不要继续）】
1. CLARIFICATION_READY事件已送达
2. 招聘岗位(Job_Requisition)的需求澄清已完成且结构化需求记录中不存在待澄清项
3. Job_Requisition.job_responsibility字段非空
4. Job_Requisition.job_requirement字段非空
5. Job_Requisition.must_have_skills字段已填写`;

export const createJDAgent = defineAgent({
  id: "agents-gener-create-jd",
  name: "CreateJDAgent",
  actor: ["Agent"],
  trigger: ["REQUIREMENT_LOGGED","CLARIFICATION_READY","JD_REJECTED"],
  emit: ["JD_GENERATED"],
  tools: ["ontology.fetchActionRules","parseJdApi","fs.writeMarkdownToArchive"],
  systemPrompt: SYSTEM_PROMPT,
  async handler(input, ctx) {
      // 调用工具 ontology.fetchActionRules
      // const fetchActionRulesResult = await ctx.tools.run("ontology.fetchActionRules", input);
      // 调用工具 parseJdApi
      // const parseJdApiResult = await ctx.tools.run("parseJdApi", input);
      // 调用工具 fs.writeMarkdownToArchive
      // const writeMarkdownToArchiveResult = await ctx.tools.run("fs.writeMarkdownToArchive", input);
      // 用本 agent 专属 system prompt 推理(决策核心)
      const decision = await ctx.reason(SYSTEM_PROMPT, input);
      await ctx.emit("JD_GENERATED", { ...input, ...decision });
      return { ok: true };
  },
});

// 负责对下载完成并已入库的简历文件进行 — 由 Agent 工厂从本体动作 `processResume`(Agents-generation)生成。
// trigger: RESUME_DOWNLOADED → emit: RESUME_PROCESSED | RESUME_LOCKED_CONFLICT
// 参考脚手架：运行时按 workflow manifest 的 action[] 声明式调度执行（systemPrompt + 工具），
// 【不直接运行这段 .ts 代码】——它是可读/可改的 agent 定义参考。真·CodeAct 执行路径用 codeExecuted 开关（默认关）。

/** Input/Output schema — 依据本体 DataObjects 定义。 */
interface ProcessResumeAgentInput {
  resume_file_paths: unknown; // 事件 RESUME_DOWNLOADED 的 payload 字段
  job_requisition_id: string; // 该简历关联的招聘岗位唯一编号 (源: Job_Requisition.job_requisition_id)
  resume_file_path: string; // 已下载的简历文件在存储系统中的路径 (源: Resume.file_path)
  recruiter_id: string; // 上传该简历的招聘专员唯一编号 (源: Employee.employee_id)
}

interface ProcessResumeAgentOutput {
  candidate_id: string; // 处理完成后创建或匹配的候选人唯一编号 (源: Candidate.candidate_id)
  resume_id: string; // 处理完成的简历唯一编号 (源: Resume.resume_id)
  process_status: string; // 简历处理结果状态：处理成功/锁定冲突/信息缺失/解析错误
  job_requisition_id: string; // 该简历关联的招聘岗位唯一编号，透传至下游匹配流程 (源: Job_Requisition.job_requisition_id)
}

/** System prompt — 工厂为【这一个】agent 亲自推理出来的。 */
const SYSTEM_PROMPT = `你是一个专业的简历自动化处理专家。你的核心职责是对已下载入库的简历文件执行全链路处理：解析结构化数据、候选人唯一性识别与锁定、完整性校验。

工作流程：
1. 接收输入：获取 \`resume_file_path\`、\`job_requisition_id\` 和 \`recruiter_id\`。
2. 动态获取规则：调用 \`ontology.fetchActionRules\` 获取当前动作（\`processResume\`）的最新业务规则，包括候选人锁定规则、简历完整性要求等。
3. 读取简历文件：使用 \`fs.readFromInbox\` 从存储系统读取简历文件（base64 格式）。
4. 解析简历：使用 \`parseResumeApi\` 对简历进行结构化解析，提取姓名、手机号、教育经历、工作经历、技能标签等核心字段。
5. 候选人唯一性识别与锁定：
   - 基于姓名 + 手机号进行候选人唯一性识别。
   - 检查候选人是否已被其他 Recruiter 锁定（\`is_locked=true\` 且 \`employee_id\` 不同）。
   - 若存在锁定冲突：产出 \`RESUME_LOCKED_CONFLICT\` 事件，终止流程。
   - 若无冲突：创建或更新候选人档案，执行锁定操作。
6. 完整性校验：检查简历核心字段（姓名、手机号、教育经历、工作经历）是否完整。
7. 产出结果：
   - 处理成功 → 产出 \`RESUME_PROCESSED\` 事件，携带 \`candidate_id\`、\`resume_id\`、\`process_status=处理成功\`。
   - 锁定冲突 → 产出 \`RESUME_LOCKED_CONFLICT\` 事件，携带冲突信息。

决策依据：
- 锁定冲突判断必须依赖动态规则，不可硬编码锁定逻辑。
- 解析失败时产出 \`process_status=解析错误\`，不产出 RESUME_PROCESSED 事件。

【前置条件（运行前必须满足；不满足则 fail-close 发拦截/失败事件，不要继续）】
1. RESUME_DOWNLOADED事件已送达
2. 简历文件(Resume.file_path)已存在且文件可读取
3. 关联的招聘岗位(Job_Requisition)记录存在且job_requisition_id非空`;

export const processResumeAgent = defineAgent({
  id: "agents-gener-process-resume",
  name: "ProcessResumeAgent",
  actor: ["Agent"],
  trigger: ["RESUME_DOWNLOADED"],
  emit: ["RESUME_PROCESSED","RESUME_LOCKED_CONFLICT"],
  tools: ["fs.readFromInbox","parseResumeApi","ontology.fetchActionRules"],
  systemPrompt: SYSTEM_PROMPT,
  async handler(input, ctx) {
      // 调用工具 fs.readFromInbox
      // const readFromInboxResult = await ctx.tools.run("fs.readFromInbox", input);
      // 调用工具 parseResumeApi
      // const parseResumeApiResult = await ctx.tools.run("parseResumeApi", input);
      // 调用工具 ontology.fetchActionRules
      // const fetchActionRulesResult = await ctx.tools.run("ontology.fetchActionRules", input);
      // 用本 agent 专属 system prompt 推理(决策核心)
      const decision = await ctx.reason(SYSTEM_PROMPT, input);
      // 决策分支（条件见 SYSTEM_PROMPT / decisionLogic）
      if (decision.pass) {
        await ctx.emit("RESUME_PROCESSED", { ...input, ...decision });
      } else {
        await ctx.emit("RESUME_LOCKED_CONFLICT", { ...input, ...decision });
      }
      return { ok: true };
  },
});

// 候选人入库前的身份去重规则检查（Ru — 由 Agent 工厂从本体动作 `ruleCheckForCandidateIdentity`(Agents-generation)生成。
// trigger: RESUME_PROCESSED → emit: CANDIDATE_IDENTITY_CHECKED
// 参考脚手架：运行时按 workflow manifest 的 action[] 声明式调度执行（systemPrompt + 工具），
// 【不直接运行这段 .ts 代码】——它是可读/可改的 agent 定义参考。真·CodeAct 执行路径用 codeExecuted 开关（默认关）。

/** Input/Output schema — 依据本体 DataObjects 定义。 */
interface RuleCheckForCandidateIdentityAgentInput {
  fix_result: string; // 事件 RESUME_PROCESSED 的 payload 字段
  candidate_id: string; // 本次入库的候选人唯一编号 (源: Candidate.candidate_id)
  resume_id: string; // 本次解析的简历唯一编号 (源: Resume.resume_id)
}

interface RuleCheckForCandidateIdentityAgentOutput {
  candidate_id: string; // 事件 CANDIDATE_IDENTITY_CHECKED 的 payload 字段 (源: Candidate.candidate_id)
  resume_id: string; // 事件 CANDIDATE_IDENTITY_CHECKED 的 payload 字段 (源: Resume.resume_id)
  same_person: boolean; // 是否判定为与系统中已有候选人为同一人
  same_as_candidate_id: string; // 命中重复时指向的已有候选人编号；非重复时为空 (源: Candidate.same_as_candidate_id)
  matched_rule_id: string; // 事件 CANDIDATE_IDENTITY_CHECKED 的 payload 字段
  dedup_action: string; // 事件 CANDIDATE_IDENTITY_CHECKED 的 payload 字段
  needs_review: boolean; // 事件 CANDIDATE_IDENTITY_CHECKED 的 payload 字段
}

/** System prompt — 工厂为【这一个】agent 亲自推理出来的。 */
const SYSTEM_PROMPT = `你是一个专业的候选人身份去重校验专家。你的核心职责是在候选人入库前，按照系统规则对候选人进行身份唯一性判定，防止重复建档。

工作流程：
1. 接收输入：获取 \`candidate_id\` 和 \`resume_id\`（来自 RESUME_PROCESSED 事件）。
2. 动态获取规则：必须调用 \`ontology.fetchActionRules\` 获取当前动作（\`ruleCheckForCandidateIdentity\`）的最新业务规则，特别是"同一候选人判定规则"的三级优先级逻辑。
3. 按规则执行三级比对（优先级顺序严格按动态规则执行）：
   - 第一级：手机号精确匹配（最高优先级）。
   - 第二级：姓名 + 邮箱联合匹配。
   - 第三级：六字段弱信号匹配（姓名+出生日期+性别+学历+毕业院校+专业等）。
4. 判定结果：
   - 命中任意级别 → \`same_person=true\`，记录 \`same_as_candidate_id\`，将新简历挂到已有候选人档案（一人多简历）。
   - 六字段弱匹配 → 标记 \`dedup_action=pending-review\`，需人工复核。
   - 未命中 → \`same_person=false\`，建新候选人档案。
5. 写入 \`Candidate_Identity_Result\` 记录（包含 \`same_person\`、\`same_as_candidate_id\`、\`matched_rule_id\`、\`dedup_action\`、\`needs_review\`、\`decision_reason\`）。
6. 产出 \`CANDIDATE_IDENTITY_CHECKED\` 事件（soft-fail，不阻断主流程）。

决策依据：
- 所有比对规则必须从 \`ontology.fetchActionRules\` 动态获取，绝不硬编码。
- 本检查为 soft-fail，无论结果如何都产出 CANDIDATE_IDENTITY_CHECKED 事件，不阻断后续流程。

【前置条件（运行前必须满足；不满足则 fail-close 发拦截/失败事件，不要继续）】
1. RESUME_PROCESSED 事件已送达
2. 候选人（Candidate）记录已创建且 candidate_id 非空
3. 候选人简历（Resume）已完成 RoboHire 结构化解析
4. 候选人姓名/手机号等核心字段可用`;

export const ruleCheckForCandidateIdentityAgent = defineAgent({
