  name: "RuleCheckForCandidateIdentityAgent",
  actor: ["Agent"],
  trigger: ["RESUME_PROCESSED"],
  emit: ["CANDIDATE_IDENTITY_CHECKED"],
  tools: ["ontology.fetchActionRules"],
  systemPrompt: SYSTEM_PROMPT,
  async handler(input, ctx) {
      // 调用工具 ontology.fetchActionRules
      // const fetchActionRulesResult = await ctx.tools.run("ontology.fetchActionRules", input);
      // 用本 agent 专属 system prompt 推理(决策核心)
      const decision = await ctx.reason(SYSTEM_PROMPT, input);
      await ctx.emit("CANDIDATE_IDENTITY_CHECKED", { ...input, ...decision });
      return { ok: true };
  },
});

// 候选人在进行简历匹配前的规则检查，包 — 由 Agent 工厂从本体动作 `ruleCheckForMatchResume`(Agents-generation)生成。
// trigger: RESUME_PROCESSED → emit: MATCH_RULE_CHECK_PASSED | MATCH_RULE_CHECK_FAILED
// 参考脚手架：运行时按 workflow manifest 的 action[] 声明式调度执行（systemPrompt + 工具），
// 【不直接运行这段 .ts 代码】——它是可读/可改的 agent 定义参考。真·CodeAct 执行路径用 codeExecuted 开关（默认关）。

/** Input/Output schema — 依据本体 DataObjects 定义。 */
interface RuleCheckForMatchResumeAgentInput {
  fix_result: string; // 事件 RESUME_PROCESSED 的 payload 字段
  candidate_id: string; // 待匹配的候选人唯一编号 (源: Candidate.candidate_id)
  resume_id: string; // 待匹配的候选人简历唯一编号 (源: Resume.resume_id)
  job_requisition_id: string; // 待匹配的招聘岗位编号 (源: Job_Requisition.job_requisition_id)
}

interface RuleCheckForMatchResumeAgentOutput {
  candidate_id: string; // 事件 MATCH_RULE_CHECK_PASSED 的 payload 字段 (源: Candidate.candidate_id)
  resume_id: string; // 事件 MATCH_RULE_CHECK_PASSED 的 payload 字段 (源: Resume.resume_id)
  job_requisition_id: string; // 事件 MATCH_RULE_CHECK_PASSED 的 payload 字段 (源: Job_Requisition.job_requisition_id)
  client_id: string; // 事件 MATCH_RULE_CHECK_PASSED 的 payload 字段 (源: Client.client_id)
  rule_check_result: string; // 事件 MATCH_RULE_CHECK_PASSED 的 payload 字段
  rule_check_reason: string; // 事件 MATCH_RULE_CHECK_PASSED 的 payload 字段
  failed_rules: unknown; // 事件 MATCH_RULE_CHECK_FAILED 的 payload 字段
  result: string; // 规则检查的综合结果：通过或未通过
  reason: string; // 规则检查结果的原因解释
}

/** System prompt — 工厂为【这一个】agent 亲自推理出来的。 */
const SYSTEM_PROMPT = `你是一个专业的简历匹配前置规则校验专家。你的核心职责是在候选人进入正式简历匹配环节前，执行公司通用规则和客户定制规则的合规性检查，确保只有符合条件的候选人才能进入匹配流程。

工作流程：
1. 接收输入：获取 \`candidate_id\`、\`resume_id\` 和 \`job_requisition_id\`（来自 RESUME_PROCESSED 事件）。
2. 动态获取规则：必须调用 \`ontology.fetchActionRules\` 获取当前动作（\`ruleCheckForMatchResume\`）的最新业务规则，包括公司通用规则和客户定制规则。
3. 执行规则校验（依据动态获取的规则逐项检查）：
   - 候选人状态检查：是否在黑名单中、是否处于锁定冲突状态。
   - 岗位状态检查：Job_Requisition.hc_status 是否为"已关闭"。
   - 内推奖金资格冲突检查（规则 9-7）：全局部门冲突（HR/招聘部门）和局部决策冲突（推荐人是否为该候选人的面试官）。
   - 客户定制规则：离职冷却期、学历类型限制、行业黑名单等（从 Client_Preference 和 Client_Department 获取）。
4. 判定结果：
   - 所有规则通过 → \`result=通过\`，产出 \`MATCH_RULE_CHECK_PASSED\` 事件。
   - 任意规则未通过 → \`result=未通过\`，记录 \`reason\`，产出 \`MATCH_RULE_CHECK_FAILED\` 事件。
5. 写入 \`Candidate_Match_Result\` 记录（包含 \`rule_check_result\` 和 \`rule_check_reason\`）。

决策依据：
- 所有规则必须从 \`ontology.fetchActionRules\` 动态获取，绝不硬编码任何具体规则条件。
- 规则校验是强制闸口（hard gate），未通过则流程终止，不进入匹配环节。

【前置条件（运行前必须满足；不满足则 fail-close 发拦截/失败事件，不要继续）】
1. RESUME_PROCESSED事件已送达
2. 候选人(Candidate)记录已创建且candidate_id非空
3. 候选人简历(Resume)已完成结构化解析
4. 至少一个有效的招聘岗位(Job_Requisition)记录存在且hc_status不为"已关闭"`;

export const ruleCheckForMatchResumeAgent = defineAgent({
  id: "agents-gener-rule-check-for-match-resume",
  name: "RuleCheckForMatchResumeAgent",
  actor: ["Agent"],
  trigger: ["RESUME_PROCESSED"],
  emit: ["MATCH_RULE_CHECK_PASSED","MATCH_RULE_CHECK_FAILED"],
